/**
 * Application-level error carrying an HTTP status code and a RealWorld-shaped
 * `errors` body, e.g. `{ errors: { field: ["message"] } }`.
 */
export class ApiError extends Error {
  status: number;
  errors: Record<string, string[]>;

  constructor(status: number, errors: Record<string, string[]>) {
    super("ApiError");
    this.status = status;
    this.errors = errors;
  }
}

export function unprocessable(errors: Record<string, string[]>): ApiError {
  return new ApiError(422, errors);
}

export function notFound(entity: string): ApiError {
  return new ApiError(404, { [entity]: ["not found"] });
}

export function forbidden(entity: string): ApiError {
  return new ApiError(403, { [entity]: ["forbidden"] });
}

export function conflict(field: string): ApiError {
  return new ApiError(409, { [field]: ["has already been taken"] });
}

