import { FastifyReply, FastifyRequest } from "fastify";
import jwt from "jsonwebtoken";
import { ApiError } from "./errors";
import { prisma } from "./prisma";

const JWT_SECRET = process.env.JWT_SECRET || "realworld-dev-secret-change-me";

export interface TokenPayload {
  id: number;
}

export function signToken(userId: number): string {
  return jwt.sign({ id: userId }, JWT_SECRET, { expiresIn: "30d" });
}

/**
 * Extracts and verifies the JWT from an `Authorization: Token <jwt>` header.
 * Returns the user id, or null when the header is absent or invalid.
 */
function userIdFromHeader(req: FastifyRequest): number | null {
  const header = req.headers.authorization;
  if (!header) return null;

  const match = header.match(/^(Token|Bearer)\s+(.+)$/i);
  const raw = match ? match[2] : header;

  try {
    const payload = jwt.verify(raw, JWT_SECRET) as TokenPayload;
    return typeof payload.id === "number" ? payload.id : null;
  } catch {
    return null;
  }
}

/**
 * preHandler enforcing authentication. Missing/invalid token -> 401.
 * On success, `req.userId` is populated.
 */
export async function requireAuth(req: FastifyRequest, _reply: FastifyReply): Promise<void> {
  const id = userIdFromHeader(req);
  if (id === null) {
    throw new ApiError(401, { token: ["is missing"] });
  }
  const user = await prisma.user.findUnique({ where: { id } });
  if (!user) {
    throw new ApiError(401, { token: ["is missing"] });
  }
  req.userId = id;
}

/**
 * preHandler that populates `req.userId` when a valid token is present but
 * never rejects the request.
 */
export async function optionalAuth(req: FastifyRequest, _reply: FastifyReply): Promise<void> {
  const id = userIdFromHeader(req);
  if (id === null) {
    req.userId = null;
    return;
  }
  const user = await prisma.user.findUnique({ where: { id } });
  req.userId = user ? id : null;
}

