import { signToken } from "./auth";

/**
 * Shared Prisma `include` shapes. We always pull the follower/favorite id lists
 * so presenters can derive `following`/`favorited` for the current viewer
 * without conditional includes.
 */
export const articleInclude = {
  tags: true,
  favoritedBy: { select: { id: true } },
  author: { include: { followers: { select: { id: true } } } },
} as const;

export const commentInclude = {
  author: { include: { followers: { select: { id: true } } } },
} as const;

type AuthorLike = {
  username: string;
  bio: string | null;
  image: string | null;
  followers: { id: number }[];
};

function following(followers: { id: number }[], viewerId: number | null): boolean {
  return viewerId != null && followers.some((f) => f.id === viewerId);
}

export function userResponse(user: {
  id: number;
  email: string;
  username: string;
  bio: string | null;
  image: string | null;
}) {
  return {
    user: {
      email: user.email,
      token: signToken(user.id),
      username: user.username,
      bio: user.bio,
      image: user.image,
    },
  };
}

export function profileResponse(user: AuthorLike, viewerId: number | null) {
  return {
    profile: {
      username: user.username,
      bio: user.bio,
      image: user.image,
      following: following(user.followers, viewerId),
    },
  };
}

type ArticleWithRelations = {
  slug: string;
  title: string;
  description: string;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  tags: { name: string }[];
  favoritedBy: { id: number }[];
  author: AuthorLike;
};

export function articleResponse(
  article: ArticleWithRelations,
  viewerId: number | null,
  includeBody = true
) {
  const author = article.author;
  const view: Record<string, unknown> = {
    slug: article.slug,
    title: article.title,
    description: article.description,
    tagList: article.tags.map((t) => t.name).sort(),
    createdAt: article.createdAt.toISOString(),
    updatedAt: article.updatedAt.toISOString(),
    favorited: viewerId != null && article.favoritedBy.some((u) => u.id === viewerId),
    favoritesCount: article.favoritedBy.length,
    author: {
      username: author.username,
      bio: author.bio,
      image: author.image,
      following: following(author.followers, viewerId),
    },
  };
  if (includeBody) view.body = article.body;
  return { article: view };
}

export function articlesResponse(
  articles: ArticleWithRelations[],
  articlesCount: number,
  viewerId: number | null
) {
  return {
    articles: articles.map((a) => articleResponse(a, viewerId, false).article),
    articlesCount,
  };
}

type CommentWithRelations = {
  id: number;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: AuthorLike;
};

export function commentResponse(comment: CommentWithRelations, viewerId: number | null) {
  const author = comment.author;
  return {
    comment: {
      id: comment.id,
      body: comment.body,
      createdAt: comment.createdAt.toISOString(),
      updatedAt: comment.updatedAt.toISOString(),
      author: {
        username: author.username,
        bio: author.bio,
        image: author.image,
        following: following(author.followers, viewerId),
      },
    },
  };
}

