import { FastifyInstance } from "fastify";
import bcrypt from "bcryptjs";
import { prisma } from "../prisma";
import { requireAuth } from "../auth";
import { ApiError, conflict, unprocessable } from "../errors";
import { userResponse } from "../presenters";

const MIN_PASSWORD_LENGTH = 8;

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

export default async function usersRoutes(app: FastifyInstance) {
  // Registration
  app.post("/users", async (req, reply) => {
    const user = ((req.body as any)?.user ?? {}) as Record<string, unknown>;
    const errors: Record<string, string[]> = {};

    if (!isNonEmptyString(user.username)) errors.username = ["can't be blank"];
    if (!isNonEmptyString(user.email)) errors.email = ["can't be blank"];
    if (!isNonEmptyString(user.password)) errors.password = ["can't be blank"];
    if (Object.keys(errors).length > 0) throw unprocessable(errors);

    const username = (user.username as string).trim();
    const email = (user.email as string).trim();

    if (await prisma.user.findUnique({ where: { username } })) throw conflict("username");
    if (await prisma.user.findUnique({ where: { email } })) throw conflict("email");

    const created = await prisma.user.create({
      data: {
        username,
        email,
        password: await bcrypt.hash(user.password as string, 10),
      },
    });

    reply.code(201);
    return userResponse(created);
  });

  // Login
  app.post("/users/login", async (req) => {
    const user = ((req.body as any)?.user ?? {}) as Record<string, unknown>;
    const errors: Record<string, string[]> = {};

    if (!isNonEmptyString(user.email)) errors.email = ["can't be blank"];
    if (!isNonEmptyString(user.password)) errors.password = ["can't be blank"];
    if (Object.keys(errors).length > 0) throw unprocessable(errors);

    const found = await prisma.user.findUnique({ where: { email: (user.email as string).trim() } });
    if (!found || !(await bcrypt.compare(user.password as string, found.password))) {
      throw new ApiError(401, { credentials: ["invalid"] });
    }
    return userResponse(found);
  });

  // Current user
  app.get("/user", { preHandler: requireAuth }, async (req) => {
    const found = await prisma.user.findUnique({ where: { id: req.userId! } });
    return userResponse(found!);
  });

  // Update current user
  app.put("/user", { preHandler: requireAuth }, async (req) => {
    const user = ((req.body as any)?.user ?? {}) as Record<string, unknown>;
    const errors: Record<string, string[]> = {};
    const data: Record<string, unknown> = {};

    // username / email: required (non-nullable) when provided.
    for (const field of ["username", "email"] as const) {
      if (field in user) {
        if (!isNonEmptyString(user[field])) {
          errors[field] = ["can't be blank"];
        } else {
          data[field] = (user[field] as string).trim();
        }
      }
    }

    // password: required when provided, min length enforced.
    if ("password" in user) {
      const pw = user.password;
      if (typeof pw !== "string" || pw.length < MIN_PASSWORD_LENGTH) {
        errors.password = ["is too short (minimum is 8 characters)"];
      } else {
        data.password = await bcrypt.hash(pw, 10);
      }
    }

    // bio / image: nullable; empty string normalizes to null.
    for (const field of ["bio", "image"] as const) {
      if (field in user) {
        const v = user[field];
        data[field] = isNonEmptyString(v) ? (v as string) : null;
      }
    }

    if (Object.keys(errors).length > 0) throw unprocessable(errors);

    // Guard against unique-constraint collisions on username/email.
    if (typeof data.username === "string") {
      const existing = await prisma.user.findUnique({ where: { username: data.username } });
      if (existing && existing.id !== req.userId) throw conflict("username");
    }
    if (typeof data.email === "string") {
      const existing = await prisma.user.findUnique({ where: { email: data.email } });
      if (existing && existing.id !== req.userId) throw conflict("email");
    }

    const updated = await prisma.user.update({ where: { id: req.userId! }, data });
    return userResponse(updated);
  });
}

