import { FastifyInstance } from "fastify";
import { prisma } from "../prisma";
import { optionalAuth, requireAuth } from "../auth";
import { forbidden, notFound, unprocessable } from "../errors";
import { commentInclude, commentResponse } from "../presenters";

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

export default async function commentsRoutes(app: FastifyInstance) {
  // Add a comment
  app.post<{ Params: { slug: string } }>(
    "/articles/:slug/comments",
    { preHandler: requireAuth },
    async (req, reply) => {
      const article = await prisma.article.findUnique({ where: { slug: req.params.slug } });
      if (!article) throw notFound("article");

      const input = ((req.body as any)?.comment ?? {}) as Record<string, unknown>;
      if (!isNonEmptyString(input.body)) throw unprocessable({ body: ["can't be blank"] });

      const created = await prisma.comment.create({
        data: {
          body: input.body as string,
          articleId: article.id,
          authorId: req.userId!,
        },
        include: commentInclude,
      });

      reply.code(201);
      return commentResponse(created, req.userId);
    }
  );

  // List comments
  app.get<{ Params: { slug: string } }>(
    "/articles/:slug/comments",
    { preHandler: optionalAuth },
    async (req) => {
      const article = await prisma.article.findUnique({ where: { slug: req.params.slug } });
      if (!article) throw notFound("article");

      const comments = await prisma.comment.findMany({
        where: { articleId: article.id },
        include: commentInclude,
        orderBy: [{ createdAt: "desc" }, { id: "desc" }],
      });
      return { comments: comments.map((c) => commentResponse(c, req.userId).comment) };
    }
  );

  // Delete a comment
  app.delete<{ Params: { slug: string; id: string } }>(
    "/articles/:slug/comments/:id",
    { preHandler: requireAuth },
    async (req, reply) => {
      const article = await prisma.article.findUnique({ where: { slug: req.params.slug } });
      if (!article) throw notFound("article");

      const commentId = parseInt(req.params.id, 10);
      const comment = Number.isFinite(commentId)
        ? await prisma.comment.findFirst({ where: { id: commentId, articleId: article.id } })
        : null;
      if (!comment) throw notFound("comment");
      if (comment.authorId !== req.userId) throw forbidden("comment");

      await prisma.comment.delete({ where: { id: comment.id } });
      reply.code(204);
      return null;
    }
  );
}

