import Fastify, { FastifyInstance } from "fastify";
import { ApiError } from "./errors";
import usersRoutes from "./routes/users";
import profilesRoutes from "./routes/profiles";
import articlesRoutes from "./routes/articles";
import commentsRoutes from "./routes/comments";
import tagsRoutes from "./routes/tags";

export function buildApp(): FastifyInstance {
  const app = Fastify({ logger: false });

  // Tolerate an empty request body on POST/PUT/DELETE (some clients send none).
  app.addContentTypeParser(
    "application/json",
    { parseAs: "string" },
    (_req, body, done) => {
      const text = (body as string).trim();
      if (text.length === 0) return done(null, {});
      try {
        done(null, JSON.parse(text));
      } catch (err) {
        done(err as Error, undefined);
      }
    }
  );

  // Uniform RealWorld error shape: { errors: { field: [messages] } }.
  app.setErrorHandler((error, _req, reply) => {
    if (error instanceof ApiError) {
      return reply.code(error.status).send({ errors: error.errors });
    }
    if ((error as any).statusCode === 400) {
      // Malformed JSON etc.
      return reply.code(422).send({ errors: { body: ["is invalid"] } });
    }
    reply.log?.error?.(error);
    return reply.code(500).send({ errors: { body: ["internal server error"] } });
  });

  app.setNotFoundHandler((_req, reply) => {
    reply.code(404).send({ errors: { route: ["not found"] } });
  });

  app.register(
    async (api) => {
      await usersRoutes(api);
      await profilesRoutes(api);
      await articlesRoutes(api);
      await commentsRoutes(api);
      await tagsRoutes(api);
    },
    { prefix: "/api" }
  );

  return app;
}

