import { randomBytes } from "crypto";
import { FastifyInstance } from "fastify";
import { prisma } from "../prisma";
import { optionalAuth, requireAuth } from "../auth";
import { forbidden, notFound, unprocessable } from "../errors";
import { articleInclude, articleResponse, articlesResponse } from "../presenters";

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function slugify(title: string): string {
  const base = title
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  // Random suffix guarantees uniqueness even for duplicate titles.
  return `${base || "article"}-${randomBytes(4).toString("hex")}`;
}

function tagConnectOrCreate(names: string[]) {
  return names.map((name) => ({
    where: { name },
    create: { name },
  }));
}

function parsePositiveInt(value: unknown, fallback: number): number {
  const n = typeof value === "string" ? parseInt(value, 10) : NaN;
  return Number.isFinite(n) && n >= 0 ? n : fallback;
}

export default async function articlesRoutes(app: FastifyInstance) {
  // Feed (must be resolvable ahead of /articles/:slug — Fastify prioritizes static routes)
  app.get("/articles/feed", { preHandler: requireAuth }, async (req) => {
    const q = req.query as Record<string, unknown>;
    const limit = parsePositiveInt(q.limit, 20);
    const offset = parsePositiveInt(q.offset, 0);

    const where = { author: { followers: { some: { id: req.userId! } } } };
    const [articlesCount, articles] = await Promise.all([
      prisma.article.count({ where }),
      prisma.article.findMany({
        where,
        include: articleInclude,
        orderBy: [{ createdAt: "desc" }, { id: "desc" }],
        take: limit,
        skip: offset,
      }),
    ]);
    return articlesResponse(articles, articlesCount, req.userId);
  });

  // List articles
  app.get("/articles", { preHandler: optionalAuth }, async (req) => {
    const q = req.query as Record<string, unknown>;
    const limit = parsePositiveInt(q.limit, 20);
    const offset = parsePositiveInt(q.offset, 0);

    const where: Record<string, unknown> = {};
    if (typeof q.tag === "string") where.tags = { some: { name: q.tag } };
    if (typeof q.author === "string") where.author = { username: q.author };
    if (typeof q.favorited === "string") where.favoritedBy = { some: { username: q.favorited } };

    const [articlesCount, articles] = await Promise.all([
      prisma.article.count({ where }),
      prisma.article.findMany({
        where,
        include: articleInclude,
        orderBy: [{ createdAt: "desc" }, { id: "desc" }],
        take: limit,
        skip: offset,
      }),
    ]);
    return articlesResponse(articles, articlesCount, req.userId);
  });

  // Create article
  app.post("/articles", { preHandler: requireAuth }, async (req) => {
    const input = ((req.body as any)?.article ?? {}) as Record<string, unknown>;
    const errors: Record<string, string[]> = {};

    if (!isNonEmptyString(input.title)) errors.title = ["can't be blank"];
    if (!isNonEmptyString(input.description)) errors.description = ["can't be blank"];
    if (!isNonEmptyString(input.body)) errors.body = ["can't be blank"];

    let tagList: string[] = [];
    if (input.tagList !== undefined) {
      if (!Array.isArray(input.tagList)) {
        errors.tagList = ["is invalid"];
      } else {
        tagList = (input.tagList as unknown[]).map(String);
      }
    }
    if (Object.keys(errors).length > 0) throw unprocessable(errors);

    const created = await prisma.article.create({
      data: {
        slug: slugify(input.title as string),
        title: (input.title as string).trim(),
        description: (input.description as string).trim(),
        body: input.body as string,
        authorId: req.userId!,
        tags: { connectOrCreate: tagConnectOrCreate(tagList) },
      },
      include: articleInclude,
    });

    return articleResponse(created, req.userId);
  });

  // Get single article
  app.get<{ Params: { slug: string } }>(
    "/articles/:slug",
    { preHandler: optionalAuth },
    async (req) => {
      const article = await prisma.article.findUnique({
        where: { slug: req.params.slug },
        include: articleInclude,
      });
      if (!article) throw notFound("article");
      return articleResponse(article, req.userId);
    }
  );

  // Update article
  app.put<{ Params: { slug: string } }>(
    "/articles/:slug",
    { preHandler: requireAuth },
    async (req) => {
      const existing = await prisma.article.findUnique({ where: { slug: req.params.slug } });
      if (!existing) throw notFound("article");
      if (existing.authorId !== req.userId) throw forbidden("article");

      const input = ((req.body as any)?.article ?? {}) as Record<string, unknown>;
      const errors: Record<string, string[]> = {};
      const data: Record<string, unknown> = {};

      for (const field of ["title", "description", "body"] as const) {
        if (field in input) {
          if (!isNonEmptyString(input[field])) {
            errors[field] = ["can't be blank"];
          } else {
            data[field] = field === "body" ? (input[field] as string) : (input[field] as string).trim();
          }
        }
      }

      let updateTags = false;
      let tagList: string[] = [];
      if ("tagList" in input) {
        if (!Array.isArray(input.tagList)) {
          errors.tagList = ["is invalid"];
        } else {
          updateTags = true;
          tagList = (input.tagList as unknown[]).map(String);
        }
      }

      if (Object.keys(errors).length > 0) throw unprocessable(errors);

      if (updateTags) {
        data.tags = { set: [], connectOrCreate: tagConnectOrCreate(tagList) };
      }

      const updated = await prisma.article.update({
        where: { id: existing.id },
        data,
        include: articleInclude,
      });
      return articleResponse(updated, req.userId);
    }
  );

  // Delete article
  app.delete<{ Params: { slug: string } }>(
    "/articles/:slug",
    { preHandler: requireAuth },
    async (req, reply) => {
      const existing = await prisma.article.findUnique({ where: { slug: req.params.slug } });
      if (!existing) throw notFound("article");
      if (existing.authorId !== req.userId) throw forbidden("article");

      await prisma.article.delete({ where: { id: existing.id } });
      reply.code(204);
      return null;
    }
  );

  // Favorite article
  app.post<{ Params: { slug: string } }>(
    "/articles/:slug/favorite",
    { preHandler: requireAuth },
    async (req) => {
      const existing = await prisma.article.findUnique({ where: { slug: req.params.slug } });
      if (!existing) throw notFound("article");

      const updated = await prisma.article.update({
        where: { id: existing.id },
        data: { favoritedBy: { connect: { id: req.userId! } } },
        include: articleInclude,
      });
      return articleResponse(updated, req.userId);
    }
  );

  // Unfavorite article
  app.delete<{ Params: { slug: string } }>(
    "/articles/:slug/favorite",
    { preHandler: requireAuth },
    async (req) => {
      const existing = await prisma.article.findUnique({ where: { slug: req.params.slug } });
      if (!existing) throw notFound("article");

      const updated = await prisma.article.update({
        where: { id: existing.id },
        data: { favoritedBy: { disconnect: { id: req.userId! } } },
        include: articleInclude,
      });
      return articleResponse(updated, req.userId);
    }
  );
}

